/**
 * Build-artifact composition report.
 *
 * `deno task bundle:report [cdn-base-url]` first builds the Bunny script, then
 * attributes generated bytes through its source map. A self-contained build is
 * also transformed with fake published asset URLs to estimate the CDN variant.
 */

import { stop, transform } from "esbuild";
import { minifyCss } from "#scripts/css-minify.ts";
import { readStaticAssets } from "#scripts/edge-bundle-lib.ts";
import {
  buildAssetPathsModule,
  buildAssetsModule,
  type PublishedAssetUrls,
} from "#scripts/edge-bundle-modules.ts";
import {
  ASSET_DEFS,
  buildCdnAssets,
  CDN_ASSET_DEFS,
} from "#scripts/edge-cdn-assets.ts";
import {
  buildRemoteModule,
  wasmFilename,
} from "#scripts/inline-jsquash-wasm.ts";
import { cleanCdnUrl } from "#scripts/static-cdn.ts";
import { utf8ByteLength } from "#shared/bytes.ts";
import { ASSETS } from "#shared/images/wasm-assets.ts";
import { countJavaScriptAstNodes } from "./javascript-ast.ts";
import {
  applicationArea,
  attributeGeneratedBytes,
  type BundleAttribution,
  type BundleCategory,
  type BundleSourceMap,
  categoryForSource,
  dependencyName,
  groupSourceBytes,
  type SourceBytes,
  sortSourceBytes,
} from "./model.ts";

const BUNDLE_PATH = "bunny-script.ts";
const MAP_PATH = "bunny-script.ts.map";
const DEFAULT_CDN_URL = "https://assets.example.com";
const INLINE_ASSETS = "inline-assets:#routes/assets.ts";
const INLINE_PATHS = "inline-asset-paths:#shared/asset-paths.ts";
const INLINE_WASM = "inline-jsquash-wasm:./wasm-bytes.ts";

const number = new Intl.NumberFormat("en-GB");
const percent = (bytes: number, total: number): string =>
  `${((bytes / total) * 100).toFixed(2)}%`;

const sourceBytes = (attribution: BundleAttribution, source: string): number =>
  attribution.bySource.find((item) => item.source === source)?.bytes ?? 0;

const sourceContent = (map: BundleSourceMap, source: string): string => {
  const index = map.sources.indexOf(source);
  if (index < 0) throw new Error(`Bundle source map is missing ${source}`);
  const content = map.sourcesContent?.[index];
  if (content === undefined || content === null) {
    throw new Error(`Bundle source map has no content for ${source}`);
  }
  return content;
};

const printTable = (
  title: string,
  rows: readonly SourceBytes[],
  total: number,
  limit = rows.length,
): void => {
  const shown = rows.slice(0, limit);
  const width = Math.max(
    "Name".length,
    ...shown.map((row) => row.source.length),
  );
  console.log(`\n${title}`);
  console.log(
    `${"Name".padEnd(width)}  ${"Bytes".padStart(12)}  ${"Share".padStart(7)}`,
  );
  for (const row of shown) {
    console.log(
      `${row.source.padEnd(width)}  ${number.format(row.bytes).padStart(12)}  ${percent(row.bytes, total).padStart(7)}`,
    );
  }
};

const groupCategories = (sources: readonly SourceBytes[]): SourceBytes[] =>
  groupSourceBytes(sources, (source) => categoryForSource(source));

const categoryBytes = (
  rows: readonly SourceBytes[],
  category: BundleCategory,
): number => rows.find((row) => row.source === category)?.bytes ?? 0;

const publishedUrls = (cdnUrl: string): PublishedAssetUrls => {
  const filenames = [
    ...CDN_ASSET_DEFS.map(([name]) => name),
    ...ASSETS.map(wasmFilename),
  ];
  return {
    origin: new URL(cdnUrl).origin,
    urls: Object.fromEntries(
      filenames.map((filename) => [
        filename,
        `${cdnUrl}/assets/bundle-report/${filename}`,
      ]),
    ),
  };
};

const parseAssignedJson = (source: string, name: string): string => {
  const prefix = `const ${name} = `;
  const line = source
    .split("\n")
    .find((candidate) => candidate.startsWith(prefix));
  if (!line?.endsWith(";"))
    throw new Error(`Generated asset module is missing ${name}`);
  return JSON.parse(line.slice(prefix.length, -1));
};

const embeddedAssets = (source: string): Record<string, string> => ({
  ...Object.fromEntries(
    ASSET_DEFS.map(([filename], index) => [
      filename,
      parseAssignedJson(source, `v${index}`),
    ]),
  ),
  "order.js": parseAssignedJson(source, "orderJsBody"),
});

const minifiedBytes = async (source: string): Promise<number> =>
  utf8ByteLength(
    (await transform(source, { format: "esm", minify: true })).code,
  );

const moduleDelta = async (
  current: string,
  replacement: string,
): Promise<number> =>
  (await minifiedBytes(replacement)) - (await minifiedBytes(current));

interface CdnEstimate {
  assetModuleBytes: number;
  totalBytes: number;
  wasmModuleBytes: number;
}

const estimateCdnBundle = async (
  map: BundleSourceMap,
  attribution: BundleAttribution,
  cdnUrl: string,
): Promise<CdnEstimate> => {
  const currentAssets = sourceContent(map, INLINE_ASSETS);
  const currentPaths = sourceContent(map, INLINE_PATHS);
  const currentWasm = sourceContent(map, INLINE_WASM);
  const published = publishedUrls(cdnUrl);
  const staticAssets = embeddedAssets(currentAssets);
  const buildTimestamp = Number(/\?ts=(\d+)/.exec(currentPaths)?.[1]);
  if (!Number.isFinite(buildTimestamp)) {
    throw new Error("Generated asset paths have no build timestamp");
  }
  const nextAssets = buildAssetsModule(ASSET_DEFS, staticAssets, published);
  const nextPaths = buildAssetPathsModule(
    ASSET_DEFS,
    buildTimestamp,
    published,
  );
  const nextWasm = buildRemoteModule(ASSETS, published.urls);
  const [assetDelta, pathDelta, wasmDelta] = await Promise.all([
    moduleDelta(currentAssets, nextAssets),
    moduleDelta(currentPaths, nextPaths),
    moduleDelta(currentWasm, nextWasm),
  ]);
  return {
    assetModuleBytes: sourceBytes(attribution, INLINE_ASSETS) + assetDelta,
    totalBytes: attribution.totalBytes + assetDelta + pathDelta + wasmDelta,
    wasmModuleBytes: sourceBytes(attribution, INLINE_WASM) + wasmDelta,
  };
};

const currentCdnBundle = (attribution: BundleAttribution): CdnEstimate => ({
  assetModuleBytes: sourceBytes(attribution, INLINE_ASSETS),
  totalBytes: attribution.totalBytes,
  wasmModuleBytes: sourceBytes(attribution, INLINE_WASM),
});

const cdnComposition = (
  attribution: BundleAttribution,
  estimate: CdnEstimate,
): SourceBytes[] => {
  const categories = groupCategories(attribution.bySource);
  const application = categoryBytes(categories, "Application source");
  const dependencies =
    categoryBytes(categories, "npm dependencies") +
    categoryBytes(categories, "JSR dependencies");
  const known =
    application +
    dependencies +
    estimate.assetModuleBytes +
    estimate.wasmModuleBytes;
  return sortSourceBytes([
    { bytes: application, source: "Application source" },
    { bytes: dependencies, source: "Dependencies" },
    {
      bytes: estimate.assetModuleBytes,
      source: "Retained assets and redirect handlers",
    },
    { bytes: estimate.wasmModuleBytes, source: "Remote WASM loader" },
    {
      bytes: estimate.totalBytes - known,
      source: "Build glue and generated code",
    },
  ]);
};

const externalObjects = (staticAssets: Record<string, string>): SourceBytes[] =>
  buildCdnAssets(staticAssets).map(({ bytes, filename }) => ({
    bytes: bytes.length,
    source: filename,
  }));

const readBuiltAssets = async (): Promise<Record<string, string>> =>
  readStaticAssets(
    await minifyCss(await Deno.readTextFile("./src/ui/static/style.css")),
  );

const main = async (): Promise<void> => {
  const [cdnArg, ...extraArgs] = Deno.args;
  if (extraArgs.length > 0) {
    throw new Error("Usage: deno task bundle:report [cdn-base-url]");
  }
  const cdnUrl = cleanCdnUrl(cdnArg ?? DEFAULT_CDN_URL);
  const [code, mapText] = await Promise.all([
    Deno.readTextFile(BUNDLE_PATH),
    Deno.readTextFile(MAP_PATH),
  ]);
  const map: BundleSourceMap = JSON.parse(mapText);
  const attribution = attributeGeneratedBytes(code, map);
  const paths = sourceContent(map, INLINE_PATHS);
  const alreadyCdn = !paths.includes("ASSET_CDN_ORIGIN = null");
  const estimate = alreadyCdn
    ? currentCdnBundle(attribution)
    : await estimateCdnBundle(map, attribution, cdnUrl);
  const staticAssets = alreadyCdn
    ? await readBuiltAssets()
    : embeddedAssets(sourceContent(map, INLINE_ASSETS));

  console.log("Bunny edge bundle composition");
  console.log(
    `${alreadyCdn ? "Current CDN-enabled build" : "Self-contained build"}: ${number.format(attribution.totalBytes)} bytes`,
  );
  console.log(
    `Parsed JavaScript AST: ${number.format(countJavaScriptAstNodes(code))} nodes`,
  );
  if (!alreadyCdn) {
    console.log(
      `Estimated CDN-enabled build: ${number.format(estimate.totalBytes)} bytes`,
    );
    console.log(`Estimate uses CDN base: ${cdnUrl}`);
  }

  printTable(
    "CDN-enabled composition",
    cdnComposition(attribution, estimate),
    estimate.totalBytes,
  );
  printTable(
    "Top dependencies",
    groupSourceBytes(attribution.bySource, dependencyName),
    estimate.totalBytes,
    15,
  );
  printTable(
    "Application areas",
    groupSourceBytes(attribution.bySource, applicationArea),
    estimate.totalBytes,
  );
  printTable(
    "Largest application files",
    attribution.bySource
      .filter((item) => item.source.startsWith("../src/"))
      .map((item) => ({
        ...item,
        source: item.source.replace(/^\.\.\/src\//, ""),
      })),
    estimate.totalBytes,
    15,
  );
  const external = sortSourceBytes(externalObjects(staticAssets));
  const externalTotal = external.reduce((sum, item) => sum + item.bytes, 0);
  printTable("External CDN objects", external, externalTotal);
  console.log(`\nExternal object total: ${number.format(externalTotal)} bytes`);
};

try {
  await main();
} finally {
  // `transform` starts esbuild's service only for self-contained estimates.
  stop();
}
